#include <cstdint>
#include <cstdlib>
#include <iostream>

struct Node {
    Node* left;
    Node* right;
};

Node* buildTree(int depth) {
    if (depth == 0) {
        return new Node{nullptr, nullptr};
    }

    Node* left = buildTree(depth - 1);
    Node* right = buildTree(depth - 1);
    return new Node{left, right};
}

std::uint64_t treeCheck(const Node* node) {
    if (node == nullptr) {
        return 0;
    }
    return 1 + treeCheck(node->left) + treeCheck(node->right);
}

void deleteTree(Node* node) {
    if (node == nullptr) {
        return;
    }

    deleteTree(node->left);
    deleteTree(node->right);
    delete node;
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        return 1;
    }

    const int n = std::atoi(argv[1]);

    Node* stretchTree = buildTree(n + 1);
    std::cout << "stretch tree of depth " << (n + 1)
              << "\t check: " << treeCheck(stretchTree) << '\n';
    deleteTree(stretchTree);

    Node* longLivedTree = buildTree(n);

    for (int depth = 4; depth <= n; depth += 2) {
        const std::uint64_t iterations =
            std::uint64_t{1} << (n - depth + 4);

        std::uint64_t check = 0;
        for (std::uint64_t i = 0; i < iterations; ++i) {
            Node* tree = buildTree(depth);
            check += treeCheck(tree);
            deleteTree(tree);
        }

        std::cout << iterations << "\t trees of depth " << depth
                  << "\t check: " << check << '\n';
    }

    std::cout << "long lived tree of depth " << n
              << "\t check: " << treeCheck(longLivedTree) << '\n';

    deleteTree(longLivedTree);
    return 0;
}
