static int n;
static std::vector<int> permutation;
static std::vector<int> work;
static long long checksum = 0;
static long long permutation_index = 0;
static int maximum_flips = 0;

static void enumerate(int length) {
    if (length == 1) {
        for (int i = 0; i < n; ++i) {
            work[i] = permutation[i];
        }

        int flips = 0;
        while (work[0] != 0) {
            const int k = work[0];
            int i = 0;
            int j = k;

            while (i < j) {
                const int tmp = work[i];
                work[i] = work[j];
                work[j] = tmp;
                ++i;
                --j;
            }
            ++flips;
        }

        if ((permutation_index & 1) == 0) {
            checksum += flips;
        } else {
            checksum -= flips;
        }

        if (flips > maximum_flips) {
            maximum_flips = flips;
        }

        ++permutation_index;
        return;
    }

    for (int i = 0; i < length; ++i) {
        enumerate(length - 1);

        const int first = permutation[0];
        for (int j = 0; j < length - 1; ++j) {
            permutation[j] = permutation[j + 1];
        }
        permutation[length - 1] = first;
    }
}

int main(int argc, char** argv) {
    if (argc < 2) {
        return 1;
    }

    n = static_cast<int>(std::strtol(argv[1], nullptr, 10));
    if (n <= 0) {
        return 1;
    }

    permutation.resize(n);
    work.resize(n);

    for (int i = 0; i < n; ++i) {
        permutation[i] = i;
    }

    enumerate(n);

    std::printf("%lld\nPfannkuchen(%d) = %d\n",
                checksum, n, maximum_flips);
    return 0;
}
