class FastOutput {
    static constexpr std::size_t BUFFER_SIZE = 1 << 20;
    char buffer[BUFFER_SIZE];
    std::size_t pos = 0;

public:
    ~FastOutput() {
        flush();
    }

    void flush() {
        if (pos != 0) {
            std::fwrite(buffer, 1, pos, stdout);
            pos = 0;
        }
    }

    void put(char c) {
        if (pos == BUFFER_SIZE) flush();
        buffer[pos++] = c;
    }

    void write(const char* s) {
        while (*s) put(*s++);
    }
};

static uint64_t seed_value = 42;

static inline double next_random() {
    seed_value = (seed_value * 3877ULL + 29573ULL) % 139968ULL;
    return static_cast<double>(seed_value) / 139968.0;
}

template <std::size_t M>
static inline char choose_symbol(
    double r,
    const std::array<char, M>& symbols,
    const std::array<double, M>& cumulative
) {
    std::size_t lo = 0;
    std::size_t hi = M;

    while (lo < hi) {
        const std::size_t mid = lo + (hi - lo) / 2;
        if (r < cumulative[mid])
            hi = mid;
        else
            lo = mid + 1;
    }

    return symbols[lo];
}

template <typename Generator>
static void write_sequence(FastOutput& out, std::size_t length, Generator generator) {
    std::size_t column = 0;

    for (std::size_t i = 0; i < length; ++i) {
        out.put(generator());

        if (++column == 60) {
            out.put('\n');
            column = 0;
        }
    }

    if (column != 0) out.put('\n');
}

int main(int argc, char** argv) {
    if (argc < 2) return 1;

    const std::size_t N = static_cast<std::size_t>(std::strtoull(argv[1], nullptr, 10));

