        "GCTGAGGCAGGAGAATCGCTTGAACCCGGGAGGCGGAGGTTGCAGTGAGCCGAGATCGCG"
        "CCACTGCACTCCAGCCTGGGCGACAGAGCGAGACTCCGTCTCAAAAA";

    FastOutput out;

    out.write(">ONE Homo sapiens alu\n");
    write_sequence(out, 2 * N, [&]() {
        static std::size_t index = 0;
        return alu[index++ % alu.size()];
    });

    constexpr std::array<char, 16> iub_symbols = {
        'a', 'c', 'g', 't',
        'B', 'D', 'H', 'K', 'M', 'N', 'R', 'S', 'V', 'W', 'Y'
    };

    constexpr std::array<double, 16> iub_probabilities = {
        0.27, 0.12, 0.12, 0.27,
        0.02, 0.02, 0.02, 0.02, 0.02, 0.02,
