    for (std::size_t i = 0; i < homo_probabilities.size(); ++i) {
        cumulative += homo_probabilities[i];
        homo_cumulative[i] = cumulative;
    }

    out.write(">THREE Homo sapiens frequency\n");
    write_sequence(out, 5 * N, [&]() {
        return choose_symbol(next_random(), homo_symbols, homo_cumulative);
    });

    out.flush();
    return 0;
}
