struct Body {
    double x, y, z;
    double vx, vy, vz;
    double mass;
};

static constexpr double PI = 3.141592653589793;
static constexpr double SOLAR_MASS = 4.0 * PI * PI;
static constexpr double DAYS_PER_YEAR = 365.24;
static constexpr double DT = 0.01;

static void offset_momentum(Body* bodies) {
    double px = 0.0;
    double py = 0.0;
    double pz = 0.0;

    for (int i = 0; i < 5; ++i) {
        px += bodies[i].vx * bodies[i].mass;
        py += bodies[i].vy * bodies[i].mass;
        pz += bodies[i].vz * bodies[i].mass;
    }

    bodies[0].vx = -px / SOLAR_MASS;
    bodies[0].vy = -py / SOLAR_MASS;
    bodies[0].vz = -pz / SOLAR_MASS;
}

static double energy(const Body* bodies) {
    double e = 0.0;

    for (int i = 0; i < 5; ++i) {
        e += 0.5 * bodies[i].mass *
             (bodies[i].vx * bodies[i].vx +
              bodies[i].vy * bodies[i].vy +
              bodies[i].vz * bodies[i].vz);

        for (int j = i + 1; j < 5; ++j) {
            const double dx = bodies[i].x - bodies[j].x;
            const double dy = bodies[i].y - bodies[j].y;
            const double dz = bodies[i].z - bodies[j].z;
            const double distance = std::sqrt(dx * dx + dy * dy + dz * dz);

            e -= (bodies[i].mass * bodies[j].mass) / distance;
        }
    }

    return e;
}

static void advance(Body* bodies, long long steps) {
    for (long long step = 0; step < steps; ++step) {
        for (int i = 0; i < 5; ++i) {
            for (int j = i + 1; j < 5; ++j) {
                const double dx = bodies[i].x - bodies[j].x;
                const double dy = bodies[i].y - bodies[j].y;
                const double dz = bodies[i].z - bodies[j].z;

                const double distance_squared =
                    dx * dx + dy * dy + dz * dz;
                const double magnitude =
                    DT / (std::sqrt(distance_squared) * distance_squared);

                bodies[i].vx -= dx * bodies[j].mass * magnitude;
                bodies[i].vy -= dy * bodies[j].mass * magnitude;
                bodies[i].vz -= dz * bodies[j].mass * magnitude;

                bodies[j].vx += dx * bodies[i].mass * magnitude;
                bodies[j].vy += dy * bodies[i].mass * magnitude;
                bodies[j].vz += dz * bodies[i].mass * magnitude;
