        case 'd': return 'h';
        case 'h': return 'd';
        case 's': return 's';
        case 'w': return 'w';
        case 'n': return 'n';

        default: return c;
    }
}

int main(int argc, char* argv[]) {
    if (argc < 2) return 1;
    (void)std::strtoll(argv[1], nullptr, 10);

    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    std::string header;
    std::string sequence;
    std::vector<std::size_t> lineLengths;
    bool haveRecord = false;

    auto flushRecord = [&]() {
        if (!haveRecord) return;

        std::cout << header << '\n';

        std::size_t pos = 0;
        for (std::size_t length : lineLengths) {
            for (std::size_t i = 0; i < length; ++i) {
                std::cout << complement(sequence[sequence.size() - 1 - (pos + i)]);
            }
            std::cout << '\n';
            pos += length;
        }

        if (lineLengths.empty() && sequence.empty()) {
            // A header-only FASTA record has no sequence lines to emit.
        }

        sequence.clear();
        lineLengths.clear();
    };

    std::string line;
    while (std::getline(std::cin, line)) {
        if (!line.empty() && line.back() == '\r') {
            line.pop_back();
        }

        if (!line.empty() && line.front() == '>') {
            flushRecord();
            header = line;
            haveRecord = true;
        } else if (haveRecord) {
            lineLengths.push_back(line.size());
            sequence += line;
        }
    }

    flushRecord();
    return 0;
}
