#include <cmath>
#include <cstdio>
#include <cstdlib>
#include <vector>
#include <algorithm>

static inline void multiplyAtA(
    int n,
    const std::vector<int>& triangular,
    const std::vector<double>& input,
    std::vector<double>& output
) {
    std::vector<double> temp(n, 0.0);

    for (int i = 0; i < n; ++i) {
        double sum = 0.0;
        const int base = i + 1;
        for (int j = 0; j < n; ++j) {
            const int denominator = triangular[i + j] + base;
            sum += input[j] / static_cast<double>(denominator);
        }
        temp[i] = sum;
    }

    std::fill(output.begin(), output.end(), 0.0);

    for (int i = 0; i < n; ++i) {
        const double value = temp[i];
        const int base = i + 1;
        for (int j = 0; j < n; ++j) {
            const int denominator = triangular[i + j] + base;
            output[j] += value / static_cast<double>(denominator);
        }
    }
}

int main(int argc, char** argv) {
    if (argc < 2) {
        return 1;
    }

    const int n = std::atoi(argv[1]);
    if (n <= 0) {
        return 1;
    }

    std::vector<int> triangular(2 * n);
    for (int k = 0; k < 2 * n; ++k) {
        triangular[k] = k * (k + 1) / 2;
    }

    std::vector<double> u(n, 1.0);
    std::vector<double> v(n, 0.0);

    for (int iteration = 0; iteration < 10; ++iteration) {
        multiplyAtA(n, triangular, u, v);
        u.swap(v);
    }

    double numerator = 0.0;
    double denominator = 0.0;

    for (int i = 0; i < n; ++i) {
        numerator += u[i] * v[i];
        denominator += v[i] * v[i];
    }

    const double estimate = std::sqrt(numerator / denominator);
    std::printf("%.9f\n", estimate);

    return 0;
}
